// Loaders for the synthetic fixture corpus under fixtures/.
//
// The corpus is generated by scripts/generate-fixtures.mjs and committed.
// Every loader validates what it reads, so a broken or tampered corpus fails
// fast instead of poisoning a downstream component.
//
// Decisions obeyed: DEC-18 (synthetic only), DEC-22 (documents + canonical
// resolutions), DEC-23 (owner + review_by), DEC-31 (770 cases split 385/385),
// section 4.11 (taxonomy of at most 25 intents including 'other').

import { readFileSync } from 'node:fs';

export const FIT_COUNT = 385;
export const REPORT_COUNT = 385;
export const INTENT_CAP = 25;

const RISK_TIERS = ['low', 'medium', 'high'] as const;
export type RiskTier = (typeof RISK_TIERS)[number];

const DOC_KINDS = ['document', 'canonical_resolution'] as const;
export type DocumentKind = (typeof DOC_KINDS)[number];

export interface Taxonomy {
  version: number;
  intent_cap: number;
  intents: TaxonomyIntent[];
}

export interface TaxonomyIntent {
  id: string;
  label: string;
  risk_tier: RiskTier;
}

export interface Disposition {
  escalated: boolean;
  macro_applied: string | null;
  refund_issued: boolean;
  first_reply_minutes: number;
}

export interface GoldTicket {
  ticket_id: string;
  source: string;
  intent: string;
  queue: string;
  disposition: Disposition;
  subject: string;
  body: string;
}

export type GoldSplit = 'fit' | 'report';

export interface GoldFile {
  split: GoldSplit;
  source: string;
  count: number;
  tickets: GoldTicket[];
}

export interface FixtureDocument {
  doc_id: string;
  kind: DocumentKind;
  title: string;
  body: string;
  url: string;
  owner: string;
  review_by: string;
  linked_intents: string[];
}

// Resolved against this module's location so both src (vitest) and dist
// (compiled) resolve to <repo>/fixtures.
export function fixturesDir(): URL {
  return new URL('../../fixtures/', import.meta.url);
}

function readJson(relative: string): unknown {
  return JSON.parse(readFileSync(new URL(relative, fixturesDir()), 'utf8'));
}

function assert(ok: boolean, message: string): asserts ok {
  if (!ok) throw new Error(`fixture validation failed: ${message}`);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Load and validate the curated taxonomy. */
export function loadTaxonomy(): Taxonomy {
  const raw = readJson('taxonomy.json');
  assert(isRecord(raw), 'taxonomy.json is not an object');
  const intents = raw['intents'];
  assert(Array.isArray(intents), 'taxonomy.intents is not an array');
  assert(intents.length <= INTENT_CAP, `taxonomy has ${intents.length} intents, cap is ${INTENT_CAP}`);
  const seen = new Set<string>();
  for (const entry of intents) {
    assert(isRecord(entry), 'taxonomy intent is not an object');
    const id = entry['id'];
    const label = entry['label'];
    const tier = entry['risk_tier'];
    assert(typeof id === 'string' && id.length > 0, 'taxonomy intent has no id');
    assert(typeof label === 'string' && label.length > 0, `intent ${id} has no label`);
    assert(
      typeof tier === 'string' && (RISK_TIERS as readonly string[]).includes(tier),
      `intent ${id} has invalid risk_tier ${String(tier)}`,
    );
    assert(!seen.has(id), `duplicate intent id ${id}`);
    seen.add(id);
  }
  assert(seen.has('other'), "taxonomy is missing the 'other' group");
  assert(
    raw['intent_cap'] === INTENT_CAP,
    `taxonomy.intent_cap is ${String(raw['intent_cap'])}, expected ${INTENT_CAP}`,
  );
  return raw as unknown as Taxonomy;
}

/** Load one half of the gold set. */
export function loadGoldHalf(split: GoldSplit): GoldFile {
  const raw = readJson(`gold/${split}.json`);
  assert(isRecord(raw), `${split}.json is not an object`);
  assert(raw['split'] === split, `gold/${split}.json declares split ${String(raw['split'])}`);
  assert(raw['source'] === 'synthetic', `gold/${split}.json is not marked synthetic`);
  const tickets = raw['tickets'];
  assert(Array.isArray(tickets), `gold/${split}.json tickets is not an array`);
  assert(tickets.length > 0, `gold/${split}.json has no tickets`);
  for (const ticket of tickets) validateTicket(ticket);
  const file = raw as unknown as GoldFile;
  assert(file.count === file.tickets.length, `gold/${split}.json count does not match its tickets`);
  return file;
}

/** Load both halves of the gold set and check the DEC-31 split discipline. */
export function loadGoldSet(): { fit: GoldFile; report: GoldFile } {
  const fit = loadGoldHalf('fit');
  const report = loadGoldHalf('report');
  assert(fit.count === FIT_COUNT, `fit half holds ${fit.count} tickets, expected ${FIT_COUNT}`);
  assert(report.count === REPORT_COUNT, `report half holds ${report.count} tickets, expected ${REPORT_COUNT}`);
  const fitIds = new Set(fit.tickets.map((t) => t.ticket_id));
  for (const ticket of report.tickets) {
    assert(!fitIds.has(ticket.ticket_id), `ticket ${ticket.ticket_id} appears in both halves`);
  }
  return { fit, report };
}

function validateTicket(value: unknown): void {
  assert(isRecord(value), 'ticket is not an object');
  assert(typeof value['ticket_id'] === 'string' && value['ticket_id'].startsWith('SYN-'), 'ticket_id must start with SYN-');
  assert(value['source'] === 'synthetic', `ticket ${String(value['ticket_id'])} is not marked synthetic`);
  assert(typeof value['intent'] === 'string', `ticket ${String(value['ticket_id'])} has no intent`);
  assert(typeof value['queue'] === 'string' && value['queue'].length > 0, `ticket ${String(value['ticket_id'])} has no queue`);
  assert(typeof value['subject'] === 'string' && value['subject'].length > 0, `ticket ${String(value['ticket_id'])} has no subject`);
  assert(typeof value['body'] === 'string' && value['body'].length > 0, `ticket ${String(value['ticket_id'])} has no body`);
  const disposition = value['disposition'];
  assert(isRecord(disposition), `ticket ${String(value['ticket_id'])} has no disposition object`);
  assert(typeof disposition['escalated'] === 'boolean', `disposition.escalated is not boolean on ${String(value['ticket_id'])}`);
  assert(
    disposition['macro_applied'] === null || typeof disposition['macro_applied'] === 'string',
    `disposition.macro_applied is neither null nor string on ${String(value['ticket_id'])}`,
  );
  assert(typeof disposition['refund_issued'] === 'boolean', `disposition.refund_issued is not boolean on ${String(value['ticket_id'])}`);
  const minutes = disposition['first_reply_minutes'];
  assert(
    typeof minutes === 'number' && Number.isInteger(minutes) && minutes >= 0,
    `disposition.first_reply_minutes is not a non-negative integer on ${String(value['ticket_id'])}`,
  );
}

/** Load and validate the retrieval corpus of documents and canonical resolutions. */
export function loadDocuments(): FixtureDocument[] {
  const raw = readJson('documents.json');
  assert(isRecord(raw), 'documents.json is not an object');
  const documents = raw['documents'];
  assert(Array.isArray(documents), 'documents.documents is not an array');
  assert(documents.length > 0, 'documents.json has no documents');
  const seen = new Set<string>();
  for (const entry of documents) {
    assert(isRecord(entry), 'document is not an object');
    const id = entry['doc_id'];
    assert(
      typeof id === 'string' && /^(DOC|RES)-SYN-/.test(id),
      `doc_id ${String(id)} must start with DOC-SYN- or RES-SYN-`,
    );
    assert(!seen.has(id), `duplicate doc_id ${id}`);
    seen.add(id);
    assert(
      typeof entry['kind'] === 'string' && (DOC_KINDS as readonly string[]).includes(entry['kind']),
      `document ${id} has invalid kind ${String(entry['kind'])}`,
    );
    // DEC-23: every document declares an owner and a review date.
    assert(typeof entry['owner'] === 'string' && entry['owner'].length > 0, `document ${id} has no owner`);
    const reviewBy = entry['review_by'];
    assert(typeof reviewBy === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(reviewBy), `document ${id} has no review_by date`);
    assert(!Number.isNaN(Date.parse(reviewBy)), `document ${id} review_by is not a valid date`);
    assert(typeof entry['title'] === 'string' && entry['title'].length > 0, `document ${id} has no title`);
    assert(typeof entry['body'] === 'string' && entry['body'].length > 0, `document ${id} has no body`);
    assert(typeof entry['url'] === 'string' && entry['url'].startsWith('https://'), `document ${id} url is not https`);
    assert(Array.isArray(entry['linked_intents']), `document ${id} linked_intents is not an array`);
    assert(entry['linked_intents'].length > 0, `document ${id} links no intents`);
  }
  return documents as unknown as FixtureDocument[];
}

/** Check that every referenced intent exists in the taxonomy. Callers that
 * need both corpora use this once instead of wiring loaders together. */
export function assertIntentsKnown(taxonomy: Taxonomy, documents: FixtureDocument[]): void {
  const known = new Set(taxonomy.intents.map((i) => i.id));
  for (const document of documents) {
    for (const intent of document.linked_intents) {
      assert(known.has(intent), `document ${document.doc_id} links unknown intent ${intent}`);
    }
  }
}
